def longest_substring_without_repeat(s):
    start = 0
    best_start = 0
    best_len = 0
    last_seen = {}
    for i, c in enumerate(s):
        if c in last_seen and last_seen[c] >= start:
            start = last_seen[c] + 1
        last_seen[c] = i
        cur_len = i - start + 1
        if cur_len > best_len:
            best_len = cur_len
            best_start = start
    return s[best_start:best_start + best_len]

def longest_palindromic_substring(s):
    if not s:
        return ''
    start, end = 0, 0

    def expand(l, r):
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1
            r += 1
        return l + 1, r - 1

    for i in range(len(s)):
        l1, r1 = expand(i, i)
        if r1 - l1 > end - start:
            start, end = l1, r1
        l2, r2 = expand(i, i + 1)
        if r2 - l2 > end - start:
            start, end = l2, r2
    return s[start:end + 1]

import string
def remove_punctuation(s):
    return ''.join(c for c in s if c not in string.punctuation)

def count_words_starting_with_vowel(s):
    vowels = set('aeiouAEIOU')
    words = s.split()
    return sum(1 for w in words if w and w[0] in vowels)

def first_repeating_char(s):
    counts = {}
    for c in s:
        counts[c] = counts.get(c, 0) + 1
    for c in s:
        if counts[c] > 1:
            return c
    return None

def is_balanced_parentheses(s):
    depth = 0
    for c in s:
        if c == '(':
            depth += 1
        elif c == ')':
            depth -= 1
            if depth < 0:
                return False
    return depth == 0

def reverse_vowels(s):
    vowels = set('aeiouAEIOU')
    chars = list(s)
    l, r = 0, len(chars) - 1
    while l < r:
        while l < r and chars[l] not in vowels:
            l += 1
        while l < r and chars[r] not in vowels:
            r -= 1
        if l < r:
            chars[l], chars[r] = chars[r], chars[l]
            l += 1
            r -= 1
    return ''.join(chars)

def is_isogram(s):
    letters = [c.lower() for c in s if c.isalpha()]
    return len(letters) == len(set(letters))

def word_wrap(s, width):
    words = s.split()
    lines = []
    current = []
    current_len = 0
    for word in words:
        if not current:
            current = [word]
            current_len = len(word)
        elif current_len + 1 + len(word) <= width:
            current.append(word)
            current_len += 1 + len(word)
        else:
            lines.append(' '.join(current))
            current = [word]
            current_len = len(word)
    if current:
        lines.append(' '.join(current))
    return lines

def count_long_words(s, min_len):
    words = s.split()
    return sum(1 for w in words if len(w) > min_len)

import string
def is_valid_identifier(s):
    if not s:
        return False
    if not (s[0] in string.ascii_letters or s[0] == '_'):
        return False
    for c in s[1:]:
        if not (c in string.ascii_letters or c in string.digits or c == '_'):
            return False
    return True

def toggle_case_by_index(s):
    result = []
    for i, c in enumerate(s):
        if i % 2 == 0:
            result.append(c.upper())
        else:
            result.append(c.lower())
    return ''.join(result)

def ends_with_any_suffix(s, suffixes):
    if not suffixes:
        return False
    return any(s.endswith(suf) for suf in suffixes)

import re
def count_sentences(s):
    parts = re.split(r'[.!?]+', s)
    return sum(1 for p in parts if p != '')

def is_palindrome_ignore_non_alnum(s):
    filtered = [c.lower() for c in s if c.isalnum()]
    return filtered == filtered[::-1]
